def demo_tables():
    tabs=[]
    for p in D:
        gi,go=p['input'],p['output']
        bgc=Counter(v for row in gi for v in row).most_common(1)[0][0]
        ch={(r,c) for r in range(len(gi)) for c in range(len(gi[0])) if gi[r][c]!=go[r][c]}
        cps=[(col,cells) for col,cells in comps2(gi)]
        Ls_=sorted([(len(cells),col,cells) for col,cells in cps if Linfo(cells)],reverse=True)
        mcol,mcells=Ls_[0][1],Ls_[0][2]
        q,_=quadrant_of_L(mcells)
        rs=Counter(r for r,c in mcells); cs=Counter(c for r,c in mcells)
        cr=max(rs,key=lambda r:rs[r]); cc=max(cs,key=lambda c:cs[c])
        classes=[]
        for col,cells in cps:
            for mem in classes:
                if len(cells)==len(mem[0][1]) and congruent(cells,mem[0][1]):
                    mem.append((col,cells)); break
            else: classes.append([(col,cells)])
        cls={}
        for mem in classes:
            for col,cells in mem: cls[id(cells)]=(len(mem),mem)
        def mind(A,B): return min(abs(a[0]-b[0])+abs(a[1]-b[1]) for a in A for b in B)
        rows=[]
        for col,cells in cps:
            csz,mem=cls[id(cells)]
            mo=sum(1 for c2,cl in mem if cl!=cells and inq(cl,q)=='no')
            cen=(sum(r for r,c in cells)/len(cells), sum(c for r,c in cells)/len(cells))
            r0,r1=q[0]; c0,c1=q[1]
            rows.append(dict(tgt=any(c in ch for c in cells), col=col, size=len(cells),
                csz=csz, mo=mo, inq=inq(cells,q),
                cq=(r0<=cen[0]<r1 and c0<=cen[1]<c1),
                dmin=mind(cells,mcells), dcor=min(abs(r-cr)+abs(c-cc) for r,c in cells),
                dmax=max(abs(r-cr)+abs(c-cc) for r,c in cells),
                bb=abs(bbox(cells)[2]-bbox(cells)[0]+1)*abs(bbox(cells)[3]-bbox(cells)[1]+1)))
        tabs.append(rows)
    return tabs
