def sym(s):
    out=[]
    cur=s
    for _ in range(4):
        out.append(frozenset(cur))
        out.append(frozenset({(r,-c) for r,c in cur}))  # mirror
        cur={(c,max(r for r,_ in s)-r) for r,c in cur}  # rough rot
    return set(out)
